  if (direction === "horizontal") {
    if (isRtl) {
      switch (getRTLOffsetType()) {
        case "negative": {
          return -scrollOffset;
        }
        case "positive-descending": {
          if (containerElement) {
            const { clientWidth, scrollWidth } = containerElement;
            return scrollWidth - clientWidth - scrollOffset;
